CREATE TABLE "MessageAttachmentReference" ("ownerType" INTEGER NOT NULL, "ownerRowId" INTEGER NOT NULL REFERENCES "model_TSInteraction"("id") ON DELETE CASCADE, "attachmentRowId" INTEGER NOT NULL REFERENCES "Attachment"("id") ON DELETE CASCADE, "receivedAtTimestamp" INTEGER NOT NULL, "contentType" INTEGER, "renderingFlag" INTEGER NOT NULL, "idInMessage" TEXT, "orderInMessage" INTEGER, "threadRowId" INTEGER NOT NULL REFERENCES "model_TSThread"("id") ON DELETE CASCADE, "caption" TEXT, "sourceFilename" TEXT, "sourceUnencryptedByteCount" INTEGER, "sourceMediaHeightPixels" INTEGER, "sourceMediaWidthPixels" INTEGER, "stickerPackId" BLOB, "stickerId" INTEGER, isVisualMediaContentType AS (contentType = 2 OR contentType = 3 OR contentType = 4) VIRTUAL, isInvalidOrFileContentType AS (contentType = 0 OR contentType = 1) VIRTUAL, "isViewOnce" BOOLEAN NOT NULL DEFAULT 0, "ownerIsPastEditRevision" BOOLEAN DEFAULT 0, "mimeType" TEXT, isGifsCategory AS (
    (contentType = 3 AND renderingFlag = 3)
    OR (contentType = 2 AND mimeType = 'image/gif')
) VIRTUAL, isPhotosCategory AS (
    contentType = 2 AND mimeType != 'image/gif'
) VIRTUAL)
